import { describe, expect, it } from 'vitest';
import type { Database } from '@/types/supabase.types';
import { BiometricStatNames, type BiometricStatName } from '../types';

/** Every `*_weight`/`*_wing` column the generated by-species cache row carries. */
type BiometricCacheColumn = Extract<
	keyof Database['public']['Tables']['SimpleStatsCacheBySpecies']['Row'],
	`${string}_weight` | `${string}_wing`
>;

/** Mutual assignability — `true` only when the two unions are the same set. */
type IsExactly<Actual, Expected> = [Actual] extends [Expected]
	? [Expected] extends [Actual]
		? true
		: false
	: false;

describe('BiometricStatNames', () => {
	it('lists every biometric column the SimpleStatsCacheBySpecies row type carries, and nothing else', () => {
		// `tsc` is the real assertion: the const is hand-written while the table
		// type is generated, so this annotation stops only typechecking while the
		// two are still the same set — a biometric column added to (or removed
		// from) the table can't leave the const silently stale.
		const everyBiometricColumnIsNamed: IsExactly<
			BiometricStatName,
			BiometricCacheColumn
		> = true;
		expect(everyBiometricColumnIsNamed).toBe(true);
	});

	it('has no duplicate entries', () => {
		expect(new Set(BiometricStatNames).size).toBe(BiometricStatNames.length);
	});
});
